// Minimal stand-in for the VS Code / Cursor API, for tests/core_test.js.
const log = [];
const mk = (pid, name) => {
  const t = { pid, name, processId: Promise.resolve(pid), sendText: (text, nl) => log.push(['send', pid, text, nl]),
    show: () => { log.push(['show', pid]); mod.window.activeTerminal = t; } };
  return t;
};
const terms = [mk(4242, 'zsh'), mk(5555, 'Other')];
const mod = {
  __log: log,
  window: { terminals: terms, activeTerminal: terms[1], state: { focused: true },
    onDidChangeWindowState: () => ({ dispose() {} }),
    createTerminal: o => { log.push(['create', o.cwd]); return mk(7777, 'claude'); } },
  commands: { executeCommand: async (c, a) => { log.push(['cmd', c, a && a.name]); if (c.endsWith('renameWithArg')) mod.window.activeTerminal.name = a.name; } },
  workspace: { workspaceFolders: [{ uri: { fsPath: '/ws' } }] },
};
module.exports = mod;
